INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('Protección de Oportunidad por 90 Días – Tu Esfuerzo, tu Comisión', 'El Partner que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el Partner que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del Partner. La protección es la garantía de que su trabajo no será aprovechado por otro.', 'Un Partner registra una oportunidad de 5 sedes. Otro Partner intenta registrar el mismo negocio dos semanas después. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del Partner original. El primer Partner tiene la tranquilidad de que su comisión de S/1,992 está asegurada si el negocio cierra dentro de los 90 días.', 16),
('Bono Extraordinario de S/2,000 – La Recompensa por el Volumen', 'Si el Partner cierra más de 20 sucursales en 3 meses (de uno o varios clientes), gana un bono adicional de S/2,000. Esto incentiva al Partner a no limitarse a uno o dos clientes pequeños, sino a buscar múltiples clientes o cuentas grandes. El bono es por volumen y se suma a las comisiones ya generadas. Es un incentivo extra para escalar.', 'Un Partner cierra en un trimestre: una cadena de 10 sedes, otra de 8 sedes, y una de 5 sedes. Total: 23 sucursales. Gana comisiones: S/6,057 + S/4,846 + S/1,992 = S/12,895. Además, gana el bono de S/2,000. Ingreso trimestral: S/14,895. El bono transforma un buen trimestre en un trimestre excepcional.', 17),
('Comisión Preferente del 10% para Cuentas Estratégicas', 'Para cuentas de alto volumen (cadenas de 15+ sucursales), INVU ofrece una comisión preferente de hasta el 10%, acordada por escrito antes del cierre. Las cuentas estratégicas requieren más esfuerzo en la prospección y el contacto inicial. El Partner merece una compensación adicional por traer oportunidades de esta escala. Esto reconoce el valor de traer cuentas grandes.', 'Un Partner identifica una cadena de 20 restaurantes. Acuerda con INVU una comisión preferente del 10% antes del cierre. Valor año 1: S/150,000. Comisión: S/15,000. En comparación con el 8% (S/12,000), el Partner gana S/3,000 adicionales. El incentivo para buscar cuentas grandes es claro.', 18),
('Partners vs. Referidos – Dos Programas, Dos Perfiles', 'El Programa de Referidos está diseñado para contactos ocasionales que quieren ganar una comisión fija por una referencia simple. El Programa Partners está diseñado para profesionales (contadores, proveedores, consultores, agencias) que tienen una red de contactos activa y quieren monetizar su influencia de manera recurrente. El referido es para abrir una puerta; el Partner es para construir una relación estratégica.', 'Un cliente satisfecho de INVU recomienda a un amigo restaurador. Gana S/1,000. Es un referido. Un contador con 20 clientes restauranteros refiere a 5 de ellos a INVU en un año. Gana S/9,960 en comisiones. Es un Partner. El referido es para contactos sueltos; el Partner es para profesionales con red.', 19),
('La Comisión del 8% – Un Ejemplo con 1 Sede', 'Para un negocio de 1 sede, el setup aproximado es S/2,450 y la licencia mensual S/350. Valor año 1: S/2,450 + 12 x S/350 = S/6,650. Comisión 8%: S/532. Pagos: 40% = S/213 (primer pago), 30% = S/160 (60 días), 30% = S/160 (90 días). El Partner cobra S/532 en 3 meses por una referencia que le tomó 1-3 horas de trabajo.', 'Un Partner refiere un restaurante de 1 sede. El cliente firma y paga su primera factura. El Partner recibe S/213 en su primer pago. A los 60 días, S/160. A los 90 días, S/160. Total: S/532. El Partner cobra rápido y sin condiciones. El esfuerzo fue mínimo; la recompensa es concreta.', 20),
('La Comisión del 8% – Un Ejemplo con 3 Sedes', 'Para un negocio de 3 sedes, el setup aproximado es S/5,250 y las licencias mensuales S/1,638. Valor año 1: S/5,250 + 12 x S/1,638 = S/24,898. Comisión 8%: S/1,992. Pagos: 40% = S/797, 30% = S/598, 30% = S/598. El Partner cobra S/1,992 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/664 a S/1,992 por hora.', 'Un contador refiere a un cliente que tiene 3 restaurantes. El cliente necesita centralización y facturación electrónica nativa. INVU cierra la venta. El contador recibe S/797 en su primer pago, S/598 a los 60 días, y S/598 a los 90 días. Total: S/1,992. El contador, que invirtió 3 horas en hacer la presentación, tiene un retorno de S/664 por hora.', 21),
('La Comisión del 8% – Un Ejemplo con 10 Sedes', 'Para una cadena de 10 sedes, el setup aproximado es S/10,150 y las licencias mensuales S/5,463. Valor año 1: S/75,708. Comisión 8%: S/6,057. Pagos: 40% = S/2,423, 30% = S/1,817, 30% = S/1,817. El Partner cobra S/6,057 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es de S/2,019 a S/6,057 por hora.', 'Un proveedor de insumos refiere una cadena de 10 restaurantes. INVU cierra la venta. El proveedor recibe S/2,423 en su primer pago, S/1,817 a los 60 días, y S/1,817 a los 90 días. Total: S/6,057. El proveedor, que invirtió 3 horas en contactar al dueño de la cadena, tiene un retorno de S/2,019 por hora. Su red de contactos se convierte en una máquina de generar dinero.', 22),
('La Comisión del 8% – Un Ejemplo con Cuenta Estratégica', 'Para una cuenta estratégica de más de 15 sedes, el valor año 1 puede superar los S/132,000. Con comisión preferente del 10%, la comisión es de S/13,200+. Pagos: 40% = S/5,280, 30% = S/3,960, 30% = S/3,960. El Partner cobra más de S/13,000 en 3 meses por una referencia que le tomó 1-3 horas de trabajo. La tasa de retorno es excepcional.', 'Un consultor refiere una cadena de 20 restaurantes. Acuerda una comisión preferente del 10% con INVU. Valor año 1: S/150,000. Comisión: S/15,000. El consultor recibe S/6,000 en su primer pago, S/4,500 a los 60 días, y S/4,500 a los 90 días. Total: S/15,000. El consultor, que invirtió 3 horas en contactar al CEO de la cadena, tiene un retorno de S/5,000 por hora. Su red de contactos se convierte en una fuente de ingresos principal.', 23),
('La Comparación con Otros Programas de Partners', 'Otros programas de partners ofrecen comisiones del 5% al 15% sobre la venta inicial, pero con condiciones: el cliente debe permanecer mínimo 12 meses, la comisión se paga fraccionada en todo ese período, y hay techos artificiales. INVU ofrece una comisión del 8% sobre el valor total del primer año, sin descuentos que reduzcan la base de cálculo, pago en tres tramos rápidos, protección de oportunidad, y bonos por rendimiento. INVU es más transparente, rápido y rentable.', 'En el programa X, la comisión es del 10%, pero el cliente debe permanecer 12 meses. Si el cliente cancela a los 8 meses, el Partner pierde parte de su comisión. En INVU, el Partner cobra el 40% al primer pago, el 30% a los 60 días, y el 30% a los 90 días. Si el cliente cancela después de los 90 días, el Partner ya cobró todo. El riesgo es menor y la transparencia es mayor.', 24),
('El Valor del Esfuerzo vs. la Comisión para el Partner', 'El Partner invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/532 (1 sede), S/1,992 (3 sedes), S/6,057 (10 sedes), o más de S/10,000 (cuenta estratégica). La tasa de retorno es excepcional: de S/177 a S/10,560 por hora. Si el Partner mantiene una red de contactos activa y refiere negocios regularmente, puede generar ingresos significativos con bajo esfuerzo.', 'Un Partner refiere 3 cadenas de 10 sedes al año. Comisión total: 3 x S/6,057 = S/18,171. Esfuerzo total: 3 x 3 horas = 9 horas. Tasa de retorno: S/2,019 por hora. El Partner gana casi S/18,000 en un año con 9 horas de trabajo. Si refiere 2 cuentas estratégicas, el ingreso supera los S/21,000. El esfuerzo es mínimo; el retorno es alto.', 25),
('El Riesgo Cero para el Partner', 'El Partner no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El Partner solo gana; nunca pierde.', 'Un Partner identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al Partner. El Partner no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo y el potencial de ganancia es alto.', 26),
('El Perfil del Partner Ideal – Profesionales con Red de Contactos', 'El Partner ideal es cualquier profesional con acceso a una red de contactos en el sector gastronómico y retail: contadores, proveedores de insumos, consultores, agencias de marketing, dueños de locales, profesionales del sector. No necesita ser vendedor tecnológico; necesita tener contactos y credibilidad. Su red de contactos es su activo más valioso. Cuanto más amplia y activa sea su red, mayor será su potencial de ingresos.', 'Un contador con 20 clientes restauranteros tiene acceso a una red valiosa. Cada cliente es una oportunidad potencial de referido. Si refiere a 5 de sus clientes a INVU en un año, puede ganar S/9,960 o más. Un proveedor de insumos con 100 clientes restauranteros tiene una red aún más grande. El Partner no necesita vender; solo necesita abrir la puerta. Su red hace el resto.', 27),
('Las 7 Preguntas del Partner – Calificar Antes de Referir', 'El Partner debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o retail, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, planes de expansión, y módulos adicionales (fidelización, e-commerce, autoservicio). Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta. También le permiten al Partner calcular su comisión potencial.', 'Un Partner contacta a un conocido dueño de una cadena de 5 restaurantes. Antes de referirlo, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, confirma que el negocio califica y que el valor potencial de la comisión es S/1,992. Ahora está motivado para referir el negocio.', 28),
('El Framework Gravity para el Partner', 'El Partner aplica el Framework Gravity de manera adaptada: Diagnóstico (identificar el negocio y hacer las 7 preguntas), Educación (presentar INVU como el socio estratégico recomendado), Comparación (mostrar que INVU integra todo en un solo sistema), Construcción de Valor (destacar los beneficios: control total, facturación nativa, e-commerce sin comisiones), y Cierre (asegurar la reunión). El Partner no cierra ventas; cierra reuniones.', 'Un Partner identifica un negocio potencial. Hace el diagnóstico: "Tienes 3 locales, pagas Nubefact aparte, no centralizas inventario." Educa: "Te recomiendo INVU, el sistema que usan más de 5,000 restaurantes en Latam." Compara: "Otros sistemas te cobran la facturación aparte; INVU lo incluye." Construye valor: "Con INVU, centralizas tus 3 locales en un solo panel." Cierra: "¿Qué te parece si los contacto para que te hagan una demo?" El Partner asegura la reunión y su comisión está en marcha.', 29),
('El Registro Correcto – Protege tu Comisión', 'El Partner debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, sistema actual, y necesidades identificadas. Sin este registro, la comisión del Partner no está protegida. Lo que no está registrado, no existe.', 'Un Partner asegura una reunión con un dueño de una cadena de 10 sedes, pero no envía el correo de registro. Otro Partner registra el mismo negocio. El primero pierde la comisión de S/6,057. El segundo cobra. El primer Partner aprende la lección: lo que no se registra, no existe. A partir de ese momento, registra todas sus oportunidades inmediatamente.', 30)) AS t(concepto, enseñanza, ejemplo, orden);